import{_ as t,c as r,o as a,ah as s}from"./chunks/framework.PvdZnrZd.js";const u=JSON.parse('{"title":"Fraud Analysis","description":"Fraud Analysis","frontmatter":{"title":"Fraud Analysis","description":"Fraud Analysis","author":"Chirag Tyagi"},"headers":[],"relativePath":"zenith/order/fraud-analysis.md","filePath":"zenith/order/fraud-analysis.md"}'),o={name:"zenith/order/fraud-analysis.md"};function n(l,e,i,d,p,h){return a(),r("div",null,[...e[0]||(e[0]=[s('<p>In a <a href="/zenith/introduction/">Multivendor Marketplace App</a>, the fraud analysis system operates in the backend to evaluate the risk associated with each customer order.</p><p>Utilizing data such as billing details, shipping addresses, IP geolocation, and transaction history, Shopify&#39;s algorithms swiftly assess the likelihood of fraud.</p><p>In the Multivendor app, the fraud analysis system flags high-risk orders and instantly notifies sellers through the marketplace app.</p><p>This action halts the fulfillment of the order until the admin has reviewed and confirmed its safety.</p><p><strong>Note: <em>When a product undergoes fraud analysis or encounters a fraud-related issue, the system sends an email to the seller,</em></strong></p><p><strong><em>Additionally, the system sends an email to the seller when it enables the fraud order restriction configuration.</em></strong></p><p>When a customer orders through a store, the respective seller can handle fulfillment of their product through the Multivendor Marketplace App.</p><p>However, In the Multivendor Marketplace App, Admin allows Sellers to fulfill orders.</p><p>This means, that if the Admin prefers to handle order fulfillment instead of allowing Sellers to do so, they can do this in the Multivendor Marketplace.</p><p>The Admin can configure whether he wants his Sellers to fulfill orders or not.</p><p>To restrict sellers from fulfilling fraud orders, the administrator must first enable the tab. For this, the admin needs to navigate.</p><p>Multi-vendor Admin Panel&gt;&gt;Configurations&gt;&gt;Order Configuration<br> After enabling the tab, the admin Restrict Seller to fulfillment for fraud orders whose fraud risk is high.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2024/07/config-1200x550.webp" alt="Fraud analysis in the Multivendor app Configuration"></p><p><strong>Note: <em>If the &quot;Restrict Seller to fulfillment for fraud orders&quot; tab is enabled in the Multi-vendor Admin Panel,</em></strong></p><p><strong><em>the system prevents sellers from fulfilling any orders flagged for fraud until the admin marks them as safe.</em></strong></p><h2 id="admin-end" tabindex="-1"><strong>ADMIN END</strong> <a class="header-anchor" href="#admin-end" aria-label="Permalink to &quot;**ADMIN END**&quot;">​</a></h2><p>Go to the Multi-vendor Admin Panel&gt;&gt;Orders&gt;&gt;Order Listing</p><p>When an order is placed by a customer with a high-risk factor, It will display a warning on the order description page.</p><p>For reference image is given below:</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2024/07/adbeforemark-538x1024.webp" alt="before mark safe by admin"></p><p>To make order safe Admin needs to click on the tab “MARK AS SAFE” and then <strong>Proceed</strong>.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2024/07/adbeforemarkk-1200x559.webp" alt="admin make order safe"></p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2024/07/adaftermarkk-1200x556.webp" alt="after mark safe by admin"></p><h2 id="seller-end" tabindex="-1"><strong>SELLER END</strong> <a class="header-anchor" href="#seller-end" aria-label="Permalink to &quot;**SELLER END**&quot;">​</a></h2><p>Now we have to navigate this from the seller&#39;s end.<br> Multi-vendor seller Panel Dashboard&gt;&gt;Orders&gt;&gt;Order Listing</p><p>Also in the respective seller panel, It will display a warning on the order description page.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2024/07/sellersidebefore-753x1024.webp" alt="seller end before mark safe by admin"></p><p>Now if a seller tries to fulfill the order the alert popup on the screen</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2024/07/selllersidebeforee-1200x539.webp" alt="risk popup"></p><p>After Marked by the admin as safe the seller can fulfill the order.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2024/07/sellersideafter-1200x558.webp" alt="After mark safe by admin "></p>',31)])])}const c=t(o,[["render",n]]);export{u as __pageData,c as default};
